import {test} from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';import {createHash} from 'node:crypto';import {resultsModel,movementText,countedScore,SCORE_COUNT_MS,FINAL_REVEAL_MS} from '../src/ui/results-model';import {OutbreakRules} from '../src/game/outbreak';
test('rank changes use competition ranks from previous cumulative totals, including ties',()=>{const r=new OutbreakRules([0,1,2,3],0);r.round=2;r.totals=[30,25,25,10];[0,20,5,0].forEach((n,i)=>r.records[i].roundPoints=n);const m=resultsModel(r.view(0),{players:[]} as any,'');assert.deepEqual(m.frogs.map(f=>[f.slot,f.previousRank,f.rank,f.movement]),[[0,1,1,0],[1,4,2,2],[2,2,2,0],[3,3,4,-1]]);assert.equal(movementText(m.frogs[1]),'↑ Up 2');assert.equal(movementText(m.frogs[3]),'↓ Down 1');assert.equal(movementText(m.frogs[0]),'— No change');});
test('first standings do not misleadingly describe all frogs as dropping from tied first',()=>{const r=new OutbreakRules([0,1],0);r.round=0;assert.ok(resultsModel(r.view(0),{players:[]}as any,'').frogs.every(f=>movementText(f)==='First standings'));});
test('count is three seconds and still halfway at midpoint; final anticipation stays brief',()=>{assert.equal(SCORE_COUNT_MS,3000);assert.equal(countedScore(0,100,1500),50);assert.equal(countedScore(0,100,1350),42.5);assert.equal(countedScore(0,100,3000),100);assert.equal(FINAL_REVEAL_MS,1800);});
test('all unrelated runtime files remain byte-identical to the preserved candidate',()=>{const m=JSON.parse(readFileSync('docs/results-refinement-preservation.json','utf8')),h=(v:any)=>createHash('sha256').update(v).digest('hex');for(const[p,v]of Object.entries(m.protected))assert.equal(h(readFileSync(p)),v,p);for(const[p,v]of Object.entries(m.files)as[string,any][]){assert.equal(h(readFileSync(p)),v.afterSha256,p);assert.equal(h(v.original),v.beforeSha256,p);}});

