import {b2sPreservedSource} from './preserved-source';
import {test} from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';import {createHash} from 'node:crypto';import {Navigator} from '../server/navigation/navigator';import {measure} from '../scripts/bot-movement-bench';
test('tactical waypoint handoff preserves every active B1 action and rope plan',()=>{for(const mode of['charge','shot','hold','flight','recover']){const nav=new Navigator(()=>.5);nav.setDestination({x:4,y:8});const n=nav as any,link={land:{x:4,y:8}};n.mode=mode;n.link=link;n.until=123;n.shotTick=42;n.attachTick=24;const progress={x:1,y:1};n.previous=progress;n.progressTick=10;nav.continueTo({x:12,y:6});assert.equal(n.mode,mode);assert.equal(n.link,link);assert.equal(n.until,123);assert.equal(n.shotTick,42);assert.equal(n.attachTick,24);assert.deepEqual(nav.goal,{x:12,y:6});assert.equal(n.previous,progress);assert.equal(n.progressTick,10);assert.equal(n.bestDistance,Infinity);}});
test('distant human tagger does not make runners camp; real inputs recover B1-level traversal',()=>{const b1=measure('B1','classic','sunny-pond',4,23,'distant-threat',1200),before=measure('Before','classic','sunny-pond',4,23,'distant-threat',1200),after=measure('After','classic','sunny-pond',4,23,'distant-threat',1200);assert.ok(after.metersPerMinute>b1.metersPerMinute*.9);assert.ok(after.platformsPerMinute>=b1.platformsPerMinute*.8);assert.ok(after.metersPerMinute>before.metersPerMinute*1.4);assert.ok(after.stationaryPct<before.stationaryPct*.7);});
test('full three-way real-physics evidence protects activity, grapples and platform transitions together',()=>{const r=JSON.parse(readFileSync(new URL('../docs/results/bot-b2-movement-correction.json',import.meta.url),'utf8')),b1=r.summary.find((r:any)=>r.version==='B1'),before=r.summary.find((r:any)=>r.version==='Before'),after=r.summary.find((r:any)=>r.version==='After');assert.ok(r.fixedCourseComparison.every((x:any)=>x.success&&x.currentSeconds===x.baselineSeconds));for(const[p,h]of Object.entries(r.sourceHashes))assert.equal(createHash('sha256').update(b2sPreservedSource(p)).digest('hex'),h);assert.equal(b1.runs,60);assert.equal(before.runs,60);assert.equal(after.runs,60);assert.ok(after.metersPerMinute>=b1.metersPerMinute*.95);assert.ok(after.platformsPerMinute>=b1.platformsPerMinute*.95);assert.ok(after.attachmentsPerMinute>=b1.attachmentsPerMinute*.75);assert.ok(after.chargedPerMinute>=b1.chargedPerMinute*.85);assert.ok(after.oscillatingPct<=b1.oscillatingPct+1);assert.ok(after.platformsPerMinute>before.platformsPerMinute*1.8);});
test('comparison fixtures are the approved B1 and rejected B2 controllers, not artificial weak opponents',()=>{const b1=JSON.parse(readFileSync(new URL('../docs/bot-b2-preservation.json',import.meta.url),'utf8')).files['server/cpu.ts'].original,old=JSON.parse(readFileSync(new URL('../docs/bot-b2r-preservation.json',import.meta.url),'utf8')).files['server/strategy/tactics.ts'].original;assert.equal(readFileSync(new URL('fixtures/b1-cpu.ts',import.meta.url),'utf8'),b1.replace("'./navigation/navigator'","'../../server/navigation/navigator'").replaceAll("'../src/","'../../src/"));assert.equal(readFileSync(new URL('fixtures/b2-tactics.ts',import.meta.url),'utf8'),old.replaceAll("'../navigation/","'../../server/navigation/").replace("'./state'","'../../server/strategy/state'"));});
test('only tactical coordination changes; the B1 executor and all approved gameplay systems remain exact',()=>{const m=JSON.parse(readFileSync(new URL('../docs/bot-b2r-preservation.json',import.meta.url),'utf8')),hash=(s:string|Buffer)=>createHash('sha256').update(s).digest('hex');for(const[p,r]of Object.entries(m.files)as[string,any][]){assert.equal(hash(r.original),r.beforeSha256,p);assert.equal(hash(b2sPreservedSource(p)),r.afterSha256,p);}for(const[p,h]of Object.entries(m.protected))assert.equal(hash(b2sPreservedSource(p)),h,p);const nav=b2sPreservedSource('server/navigation/navigator.ts'),original=m.files['server/navigation/navigator.ts'].original;assert.equal(nav.replace(/ \/\*\* Tactical waypoint handoff:[\s\S]*?\n continueTo\([^\n]*\n/,''),original);});
test('moving tactical goals cannot disable B1 spatial stuck detection',async()=>{const{makeCourse}=await import('../scripts/bot-b1-harness');const{sim,nav}=makeCourse({name:'blocked',platforms:[[20,20,40,1],[6,15,1,10]],start:[4,19],goal:[18,19]});for(let t=0;t<600;t++){if(t%12===0)nav.continueTo({x:18+(Math.floor(t/12)%2)*2,y:19});sim.setInput(0,nav.input(sim,0));sim.step();}assert.ok(nav.stats.recoveries>0);});
